    /**
     * <p>Checks whether the String a valid Java number.</p>
     *
     * <p>Valid numbers include hexadecimal (e.g., "0xFE"), scientific notation (e.g., "1.2e-3"),
     * and numbers with type qualifiers (e.g., "123L", "4.5F").
     * It also supports "Infinity", "-Infinity", and "NaN".</p>
     *
     * <p>This method is more lenient than {@link Double#parseDouble(String)}
     * as it allows for trailing decimal points (e.g., "123.") and type qualifiers.</p>
     *
     * @param str the String to check
     * @return {@code true} if the string is a valid number, {@code false} otherwise
     */
    public static boolean isNumber(String str) {
        if (str == null || str.isEmpty()) {
            return false;
        }

        char[] chars = str.toCharArray();
        int len = chars.length;
        int start = 0;
        boolean hasSign = false;
        boolean hasDecimalPoint = false;
        boolean hasExponent = false;
        boolean foundDigit = false;
        boolean allowExponentSign = false;

        // Handle initial sign
