import java.util.HashSet;
import java.util.Set;

public class StringUtils {

    public static final int INDEX_NOT_FOUND = -1;

    // Assuming isEmpty and ArrayUtils.isEmpty are available or implemented similarly
    public static boolean isEmpty(CharSequence cs) {
        return cs == null || cs.length() == 0;
    }

    // A simplified ArrayUtils.isEmpty for demonstration, assuming it's available in the real library
    public static boolean ArrayUtils_isEmpty(char[] array) {
        return array == null || array.length == 0;
    }

    /**
     * Finds the first index in the {@code CharSequence} {@code cs} that contains a character
     * that is not present in the {@code searchChars} array.
     *
     * @param cs          the {@code CharSequence} to search, may be null
     * @param searchChars the characters to search for, may be null
     * @return the index of the first character in {@code cs} that is not in {@code searchChars},
     *         or {@link #INDEX_NOT_FOUND} if {@code cs} is null or empty,
     *         or if {@code searchChars} is null or empty,
     *         or if all characters in {@code cs} are found in {@code searchChars}.
     */
    public static int indexOfAnyBut(CharSequence cs, char[] searchChars) {
        if (isEmpty(cs)) {
            return INDEX_NOT_FOUND;
        }
        if (ArrayUtils_isEmpty(searchChars)) { // If no characters to exclude, then no character can be "not in" them.
            return INDEX_NOT_FOUND;
        }

        // For improved performance with potentially large searchChars, convert to a Set for O(1) average lookup.
        // This is a more robust approach for general use cases.
        Set<Character> searchCharSet = new HashSet<>();
        for (char ch : searchChars) {
            searchCharSet.add(ch);
        }

        int csLen = cs.length();
        for (int i = 0; i < csLen; i++) {
            char ch = cs.charAt(i);
            if (!searchCharSet.contains(ch)) {
                return i;
            }
        }
        return INDEX_NOT_FOUND;
    }
}
